function lessonHttp($path,$data=null,$jar='user',$csrf=null,$headers=[]){global $jars;$jars[$jar]??=tempnam(sys_get_temp_dir(),'lesson-cookie-');$ch=curl_init(appUrl($path));$options=[CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIEFILE=>$jars[$jar],CURLOPT_COOKIEJAR=>$jars[$jar],CURLOPT_TIMEOUT=>15];if($data!==null){$options[CURLOPT_POST]=true;$multipart=count(array_filter($data,fn($v)=>$v instanceof CURLFile))>0;if($multipart)$options[CURLOPT_POSTFIELDS]=$data;elseif($csrf!==null){$options[CURLOPT_POSTFIELDS]=json_encode($data);$headers[]='Content-Type: application/json';}else $options[CURLOPT_POSTFIELDS]=http_build_query($data);}if($csrf!==null)$headers[]='X-CSRF-Token: '.$csrf;$options[CURLOPT_HTTPHEADER]=$headers;curl_setopt_array($ch,$options);$body=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);return [$status,$body,json_decode((string)$body,true)];}
